import{_ as a,o as t,c as i,a2 as r}from"./chunks/framework.CqGS6Fr9.js";const m=JSON.parse('{"title":"Monitoring and event feed","description":"","frontmatter":{"pageId":"admins/monitoring","contentRevision":5},"headers":[],"relativePath":"en/admins/monitoring.md","filePath":"en/admins/monitoring.md"}'),s={name:"en/admins/monitoring.md"};function n(o,e,l,d,c,p){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="monitoring-and-event-feed" tabindex="-1">Monitoring and event feed <a class="header-anchor" href="#monitoring-and-event-feed" aria-label="Permalink to &quot;Monitoring and event feed&quot;">​</a></h1><p>Applies to: Rimlink 0.9.2 · RimWorld 1.7 · protocol 1.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage {#usage}&quot;">​</a></h2><p>GET /health checks process availability; /metrics exposes metrics. Restrict network access and collect from a trusted host. Administrative /status returns operational state; /actions correlates changes with operators.</p><p>SSE GET /api/admin/events uses epoch:seq identifiers. Send Last-Event-ID on reconnect. A gap means restart/buffer overflow lost events: reread current state instead of deriving it from an incomplete feed. Defaults are 1000 buffered events and a ping every 15 seconds.</p><p>Monitor free disk space, the age of the last successful backup, login/save/delivery refusals and long live sessions. “Process alive” does not replace colony read/write verification.</p><h2 id="monitor-layers" tabindex="-1">Three monitoring layers <a class="header-anchor" href="#monitor-layers" aria-label="Permalink to &quot;Three monitoring layers {#monitor-layers}&quot;">​</a></h2><p>Separate process availability, application correctness and recoverability. /health covers the first; status/metrics, login/save refusals, queue/session duration cover the second. Successful-backup age and periodic isolated restore cover the third.</p><p>Compare disk trends with actual saves.diskBytes; old versions and external ZIPs can grow for different reasons. Preserve time/version/audit before intervention. Avoid private names/tokens in metrics and restrict public /metrics at the network.</p><h2 id="sse-gap" tabindex="-1">How to handle an SSE gap <a class="header-anchor" href="#sse-gap" aria-label="Permalink to &quot;How to handle an SSE gap {#sse-gap}&quot;">​</a></h2><p>Persist the last epoch:seq after processing its event and send Last-Event-ID on reconnect. Gap means the local journal is incomplete: reread status/lists, refresh your view and continue the new stream. Never invent missing events or execute mutations from replayed notifications.</p><p>A ping proves stream activity, not a new trade. Private chat/wallets/parcels and not-yet-landed raids are intentionally absent; investigate through authorized entity reads, not reconstruction from public feed.</p><h2 id="limits" tabindex="-1">Limits and safety <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits and safety {#limits}&quot;">​</a></h2><p>The feed intentionally excludes private chat, wallets, parcels and raids not yet landed. Keep tokens/full saves out of metrics and shared logs. /metrics is application-public: restrict it at the network layer.</p><h2 id="related" tabindex="-1">See also <a class="header-anchor" href="#related" aria-label="Permalink to &quot;See also {#related}&quot;">​</a></h2><ul><li><a href="./discord">Discord bot</a></li><li><a href="./troubleshooting">Administrator troubleshooting</a></li><li><a href="./api">REST API reference</a></li></ul>',16)])])}const u=a(s,[["render",n]]);export{m as __pageData,u as default};
